import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import postcss from "postcss";
import tailwind from "@tailwindcss/postcss";

/*
 * Compiles the light-DOM layout + composition utilities used by plain-html-demo.html.
 * Component chrome stays in sc-components.css inside shadow roots; this sheet only styles the page mosaic.
 */

const here = dirname(fileURLToPath(import.meta.url));
const siteRoot = resolve(here, "..");
const outDir = join(siteRoot, "public");

const cssEntry = [
  "/* Generated by scripts/build-wc-mosaic-css.mjs — do not edit. */",
  '@import "./globals.css";',
  '@source "../../public/plain-html-demo.html";',
  // Layout shells stamp Card/Table utility strings onto light-DOM hosts; scan ui + Preview02 so those utilities emit.
  '@source "../../../ui/src/main/scala/**/*.scala";',
  '@source "../main/scala/shadcnscalajs/site/create/preview02/**/*.scala";',
  ""
].join("\n");

mkdirSync(outDir, { recursive: true });
const result = await postcss([tailwind()]).process(cssEntry, {
  from: join(siteRoot, "src/styles/globals.css")
});
const outFile = join(outDir, "wc-mosaic.css");
writeFileSync(outFile, result.css);
console.log(`Built ${outFile} (${Math.round(result.css.length / 1024)} kB)`);
